function convertImportsToRequire(
  content: string,
  parseAst: any,
  query: any
): string {
  const ts = require('typescript');
  const sourceFile = parseAst(content);
  const importDeclarations = query(sourceFile, 'ImportDeclaration');

  if (importDeclarations.length === 0) {
    return content;
  }

  // Sort imports by position (descending) to replace from end to start
  // This preserves positions of earlier nodes
  const sortedImports = [...importDeclarations].sort(
    (a, b) => b.getStart() - a.getStart()
  );

  for (const importDecl of sortedImports) {
    const moduleSpecifier = importDecl.moduleSpecifier
      .getText()
      .replace(/['"]/g, '');
    const importClause = importDecl.importClause;

    if (!importClause) {
      // Side-effect import: import 'module'
      const requireStatement = `require('${moduleSpecifier}')`;
      content = replaceNode(content, importDecl, requireStatement);
      continue;
    }

    // `import type ...` is erased by Node's type-stripping at runtime, so it
    // can remain in the file untouched — this preserves editor/tsc type safety.
    if (importClause.isTypeOnly) {
      continue;
    }

    const parts: string[] = [];
    const typeOnlySpecifiers: string[] = [];

    // Default import: import x from 'module'
    if (importClause.name) {
      const defaultName = importClause.name.getText();
      parts.push(
        `const ${defaultName} = require('${moduleSpecifier}').default ?? require('${moduleSpecifier}')`
      );
    }

    if (importClause.namedBindings) {
      if (ts.isNamedImports(importClause.namedBindings)) {
        const valueSpecifiers: string[] = [];
        for (const element of importClause.namedBindings.elements) {
          const name = element.name.getText();
          const propertyName = element.propertyName?.getText();
          if (element.isTypeOnly) {
            // Inline `type` modifier: `import { type Foo, bar } from 'x'`.
            // Preserve the type-only portion so type references still resolve.
            typeOnlySpecifiers.push(
              propertyName ? `${propertyName} as ${name}` : name
            );
          } else {
            valueSpecifiers.push(
              propertyName ? `${propertyName}: ${name}` : name
            );
          }
        }
        if (valueSpecifiers.length) {
          parts.push(
            `const { ${valueSpecifiers.join(', ')} } = require('${moduleSpecifier}')`
          );
        }
      } else if (ts.isNamespaceImport(importClause.namedBindings)) {
        // Namespace import: import * as x from 'module'
        const namespaceName = importClause.namedBindings.name.getText();
        parts.push(`const ${namespaceName} = require('${moduleSpecifier}')`);
      }
    }

    const replacementParts: string[] = [];
    if (typeOnlySpecifiers.length) {
      replacementParts.push(
        `import type { ${typeOnlySpecifiers.join(', ')} } from '${moduleSpecifier}'`
      );
    }
    replacementParts.push(...parts);

    if (replacementParts.length === 0) {
      continue;
    }

    const replacement = replacementParts.join(';\n');
    content = replaceNode(content, importDecl, replacement);
  }

  return content;
}

function convertExportDefaultToModuleExports(
  content: string,
  query: any
): string {
  // Handle: export default { ... }
  const exportAssignments = query(content, 'ExportAssignment');

  if (exportAssignments.length > 0) {
    for (const exportAssignment of exportAssignments) {
      const expression = exportAssignment.expression;
      if (expression) {
        const exportedValue = expression.getText();
        const replacement = `module.exports = ${exportedValue}`;
        content = replaceNode(content, exportAssignment, replacement);
      }
    }
  }

  return content;
}

function replaceNode(content: string, node: any, replacement: string): string {
  const start = node.getStart();
  const end = node.getEnd();
  // Remove trailing semicolon if present to avoid double semicolons
  let endPos = end;
  if (content[end] === ';') {
    endPos = end + 1;
  }
  return content.slice(0, start) + replacement + ';' + content.slice(endPos);
}

