describe('smoke: skip-setup-file', () => {
  let tree: Tree;
  beforeEach(() => {
    tree = createTreeWithEmptyWorkspace();
  });

  it('rewrites true -> none, drops false, preserves existing, nested form, empty-key removal', async () => {
    updateJson<NxJsonConfiguration>(tree, 'nx.json', (json) => {
      json.generators = {
        '@nx/jest:configuration': { skipSetupFile: true },
        '@nx/react:application': { style: 'scss' },
      };
      return json;
    });
    await skipSetupFileMigration(tree);
    let nxJson = readJson<NxJsonConfiguration>(tree, 'nx.json');
    expect(nxJson.generators['@nx/jest:configuration']).toEqual({
      setupFile: 'none',
    });
    expect(nxJson.generators['@nx/react:application']).toEqual({
      style: 'scss',
    });

    // false -> drop, key removed since empty
    updateJson<NxJsonConfiguration>(tree, 'nx.json', (json) => {
      json.generators = { '@nx/jest:configuration': { skipSetupFile: false } };
      return json;
    });
    await skipSetupFileMigration(tree);
    nxJson = readJson<NxJsonConfiguration>(tree, 'nx.json');
    expect(nxJson.generators['@nx/jest:configuration']).toBeUndefined();

    // true + existing setupFile -> preserve
    updateJson<NxJsonConfiguration>(tree, 'nx.json', (json) => {
      json.generators = {
        '@nx/jest:configuration': { skipSetupFile: true, setupFile: 'angular' },
      };
      return json;
    });
    await skipSetupFileMigration(tree);
    nxJson = readJson<NxJsonConfiguration>(tree, 'nx.json');
    expect(nxJson.generators['@nx/jest:configuration']).toEqual({
      setupFile: 'angular',
