    updateJson<NxJsonConfiguration>(tree, 'nx.json', (json) => {
      json.generators = { '@nx/jest': { configuration: { skipSetupFile: true } } };
      return json;
    });
    await skipSetupFileMigration(tree);
    nxJson = readJson<NxJsonConfiguration>(tree, 'nx.json');
    expect(nxJson.generators['@nx/jest']).toBeUndefined();
  });
});

